const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'P(-3,2)' },
      { kind: 'text', payload: '第二象限' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: '-3' },
      { kind: 'text', payload: '2' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = Math.max(18, Math.min(W, H) * 0.08);
    var originX = W * 0.58;
    var originY = H * 0.58;
    var scale = Math.min(W / 12, H / 10);
    var x0 = margin;
    var x1 = W - margin;
    var y0 = H - margin;
    var y1 = margin;
    var horizontalAxis = visualSdk.axis({ x0: x0, y0: originY, x1: x1, y1: originY, ticks: 8, tickLength: 6 });
    var verticalAxis = visualSdk.axis({ x0: originX, y0: y0, x1: originX, y1: y1, ticks: 8, tickLength: 6 });
    var px = originX - 3 * scale;
    var py = originY - 2 * scale;
    var pointR = Math.max(4, scale * 0.12);
    var point = visualSdk.circle(px, py, pointR);
    var dashedToX = [['M', px, py], ['L', px, originY]];
    var dashedToY = [['M', px, py], ['L', originX, py]];
    return {
      schemaVersion: 1,
      sceneId: 'point-p-second-quadrant',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'xAxis', commands: horizontalAxis },
        { id: 'yAxis', commands: verticalAxis },
        { id: 'dashedToX', commands: dashedToX },
        { id: 'dashedToY', commands: dashedToY },
        { id: 'pointP', commands: point }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'xAxis', fill: '#26354a', stroke: { width: 2, cap: 'round', join: 'round' } },
        { type: 'path', pathId: 'yAxis', fill: '#26354a', stroke: { width: 2, cap: 'round', join: 'round' } },
        { type: 'path', pathId: 'dashedToX', fill: '#5b6b80', stroke: { width: 2, cap: 'butt', join: 'miter', dash: [6, 4] } },
        { type: 'path', pathId: 'dashedToY', fill: '#5b6b80', stroke: { width: 2, cap: 'butt', join: 'miter', dash: [6, 4] } },
        { type: 'path', pathId: 'pointP', fill: '#c0392b', stroke: { width: 2 } },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: px - pointR * 1.8, y: py - pointR * 1.8 }, hAlign: 'right', vAlign: 'bottom', color: '#c0392b' },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: W * 0.16, y: H * 0.14 }, hAlign: 'left', vAlign: 'top', color: '#26354a' },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: x1, y: originY - 8 }, hAlign: 'right', vAlign: 'bottom', color: '#26354a' },
        { type: 'label', contentId: metrics[3].contentId, anchor: { x: originX + 8, y: y1 + 2 }, hAlign: 'left', vAlign: 'top', color: '#26354a' },
        { type: 'label', contentId: metrics[4].contentId, anchor: { x: originX - 6, y: originY + 6 }, hAlign: 'right', vAlign: 'top', color: '#26354a' },
        { type: 'label', contentId: metrics[5].contentId, anchor: { x: px, y: originY + 8 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
        { type: 'label', contentId: metrics[6].contentId, anchor: { x: originX - 8, y: py }, hAlign: 'right', vAlign: 'middle', color: '#26354a' }
      ] }
    };
  }
};
